setTimeout(()=>{if(location.pathname==='/usage'&&window.usageData?.recent){usageRecentRows=window.usageData.recent;renderUsageRecent()}},900);
setTimeout(()=>{const body=document.querySelector('#usageRecent');if(body)body.dataset.synced='1'},100);
renderUsageRecent=function(){const q=($('#usageRecentSearch')?.value||'').toLowerCase().trim(),filtered=usageRecentRows.filter(x=>[x.key_name,x.vehicle,x.endpoint,x.status_code,x.cache_hit?'Cache':'Provider',x.client_ip,x.device_type,x.location_status,x.created_at].join(' ').toLowerCase().includes(q));filtered.sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));const parsedSize=Number(window.usageRecentPageSize),size=Number.isFinite(parsedSize)&&parsedSize>0?parsedSize:10,parsedPage=Number(usageRecentPage),current=Number.isFinite(parsedPage)&&parsedPage>0?Math.floor(parsedPage):1,pages=Math.max(1,Math.ceil(filtered.length/size));usageRecentPage=Math.min(current,pages);const shown=filtered.slice((usageRecentPage-1)*size,usageRecentPage*size),body=$('#usageRecent');if(!body)return;body.innerHTML=shown.map(x=>`<tr><td>${esc(x.key_name)}</td><td>${esc(x.vehicle||'—')}</td><td>${esc(x.endpoint)}</td><td>${x.status_code||'—'}</td><td>${x.cache_hit?'Cache':'Provider'}</td><td>${esc(x.client_ip||'Not recorded')}</td><td>${esc(x.device_type||'Unknown')}</td><td>${esc(x.location_status||'Not recorded')}</td><td>${new Date(x.created_at).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="9" class="muted">No matching API hits.</td></tr>';body.dataset.synced='1';const count=$('#usageRecentCount');if(count)count.textContent=`${filtered.length} results · Page ${usageRecentPage} of ${pages}`;let nav=$('#usageRecentPagination');if(!nav){nav=document.createElement('div');nav.id='usageRecentPagination';nav.className='usage-pagination';body.closest('.records-table-wrap')?.after(nav)}const start=Math.max(1,Math.min(usageRecentPage-2,pages-4)),end=Math.min(pages,start+4);nav.innerHTML=`<label class="table-page-size">Rows <select id="usageRecentPageSize"><option value="10" ${size===10?'selected':''}>10</option><option value="25" ${size===25?'selected':''}>25</option><option value="50" ${size===50?'selected':''}>50</option></select></label><button class="ghost" data-usage-page="prev" ${usageRecentPage<=1?'disabled':''}>Previous</button>${Array.from({length:Math.max(0,end-start+1)},(_,i)=>{const p=start+i;return `<button class="ghost page-number ${p===usageRecentPage?'active':''}" data-usage-page-number="${p}">${p}</button>`}).join('')}<button class="ghost" data-usage-page="next" ${usageRecentPage>=pages?'disabled':''}>Next</button>`};
$('#recordsSelectAll')?.addEventListener('change',e=>{document.querySelectorAll('#allRecords input[data-record-select]').forEach(x=>x.checked=e.target.checked);updateRecordSelection()});document.addEventListener('change',e=>{if(e.target.matches('#allRecords input[data-record-select]'))updateRecordSelection()});async function deleteVehicles(vehicles){const unique=[...new Set(vehicles)];if(!unique.length)return;if(!confirm(`Delete ${unique.length} saved vehicle${unique.length===1?'':'s'} and all cached provider records? This cannot be undone.`))return;const results=await Promise.all(unique.map(vehicle=>fetch(`/api/records/${encodeURIComponent(vehicle)}`,{method:'DELETE'})));if(results.every(r=>r.ok)){allRecords=allRecords.filter(x=>!unique.includes(x.vehicle));renderRecords()}else alert('One or more vehicles could not be deleted. Refresh and try again.')}document.addEventListener('click',e=>{const b=e.target.closest('[data-delete-vehicle]');if(b)deleteVehicles([b.dataset.deleteVehicle])});$('#recordsBulkDelete')?.addEventListener('click',()=>deleteVehicles(selectedVehicles()));
function moveRecordsSelectAllToHeader(){const label=document.querySelector('.records-select-all'),cell=document.querySelector('.records-view thead .records-check-col');if(label&&cell&&!cell.contains(label)){label.classList.add('table-select-all');cell.append(label)}}
document.addEventListener('DOMContentLoaded',moveRecordsSelectAllToHeader);
